'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import { createClient } from '@/lib/supabase'
import { Loader2 } from 'lucide-react'

export default function ScoutLayout({
    children,
}: {
    children: React.ReactNode
}) {
    const [loading, setLoading] = useState(true)
    const [authenticated, setAuthenticated] = useState(false)
    const router = useRouter()
    const supabase = createClient()

    useEffect(() => {
        const checkUser = async () => {
            const { data: { session } } = await supabase.auth.getSession()

            if (!session) {
                router.push('/login?redirect=/scout/match') // Default to match scouting
                return
            }

            setAuthenticated(true)
            setLoading(false)
        }

        checkUser()

        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
            if (!session) {
                router.push('/login')
            } else {
                setAuthenticated(true)
            }
        })

        return () => subscription.unsubscribe()
    }, [router, supabase])

    if (loading) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[calc(100vh-4rem)] space-y-4">
                <Loader2 className="h-12 w-12 animate-spin text-primary opacity-20" />
                <div className="text-muted-foreground font-bold animate-pulse text-lg uppercase tracking-widest">
                    Authenticating Scouter...
                </div>
            </div>
        )
    }

    if (!authenticated) return null

    return <>{children}</>
}
